# Search for tables containing railroad retirement data in the JSON
import json

with open('/app/resources/treasury_bulletin_1970_06.json', 'r') as f:
    data = json.load(f)

# Look for tables
def find_key(obj, target):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if target.lower() in k.lower():
                print(f"Found: {k}")
            find_key(v, target)
    elif isinstance(obj, list):
        for item in obj:
            find_key(item, target)

# Find railroad retirement
print("Searching for railroad retirement data...")
find_key(data, 'railroad')
